def is_old_enough(age:int) -> bool:
  if age > 21:
      return True
  else:
      return False

def sum_list(nums:list[int]) -> int:
   sum = 0
   nums_length = len(nums)

   for i in range(nums_length):
       sum += i

   return sum

def find_grade_average(grades:list[int]) -> float | int:
   grades_length = len(grades)
   if grades_length == 0:
      return -1
   sum = 0
   for i in range(grades_length):
       sum += grades[i]
   return sum / grades_length

def pair_with_leader(people:list[str]) -> list[str]:
    leader_index = 1
    leader = people[leader_index]
    pairs = []
    for i in range(len(people)):
        if i != leader_index:
            pairs.append(f"{leader} & {people[i]}")
    return pairs

def count_digits(num:int) -> int:
    string_num = str(num)
    total = 0
    for i in range(len(string_num)):
        if string_num[i].isdigit():
            total += 1
    return total

def distance_converter(distance:int, convert_to:str) -> float | None:
    if convert_to == "km":
        return distance * 1.609
    elif convert_to == "mi":
        return distance / 1.609

def find_largest_num(nums:list[int]) -> int:
    largest = 0
    largest_len = len(nums)
    for i in range(largest_len):
        if nums[i] > largest:
            largest = nums[i]
    return largest

def count_vowels(word:str) -> int:
    total = 0
    for i in range(len(word)):
        if word[i] == 'a' or word[i] == 'e' or word[i] == 'i' or word[i] == 'o' or word[i] == 'u':
            total += 1
    return total

def remove_duplicates(nums:list[int]) -> list[int]:
    clean_arr = []
    for i in range(len(nums)):
        if nums[i] not in clean_arr:
            clean_arr.append(nums[i])
    return clean_arr

def sum_all(nums:list[int]) -> int:
    total = 0 
    for num in nums:
        total += num
    return total

def multiply_all(nums:list[int]) -> int:
    product = 0 
    for num in nums:
        product *= num
    return product
